1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  let input = "";
5	
6	  for await (const chunk of process.stdin) {
7	    input += chunk;
8	  }
9	
10	  return input;
11	};
12	
13	// `JSON.parse` yields `any`, which would silently erase the `Scenario` contract
14	// at the very boundary where untrusted input arrives. Naming the parsed value
15	// `unknown` keeps that gap visible: nothing here has checked the scenario yet,
16	// and the cast below is where the MHPCO takes it on trust.
17	const parsedScenario = (input: string): unknown => JSON.parse(input);
18	
19	const main = async (): Promise<void> => {
20	  const scenario = parsedScenario(await readStdin()) as Scenario;
21	
22	  process.stdout.write(JSON.stringify(runScenario(scenario)));
23	};
24	
25	// The MHPCO reports a refusal as a plain description of what it objected to,
26	// and writes no results at all when it cannot process the scenario.
27	await main().catch((error: unknown) => {
28	  process.stderr.write(`${error instanceof Error ? error.message : error}\n`);
29	  process.exitCode = 1;
30	});
