252	  appliesTo: (item: Item) => boolean;
253	  percentReimbursed: number;
254	};
255	
256	const roundedDownInMHPCOsFavour = (payout: number): number =>
257	  Math.floor(payout);
258	
259	const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type];
260	
261	// A policy is created by a quote step and remembers how much of its cap the
262	// customer has already claimed.
263	type Policy = {
264	  items: Item[];
265	  remainingCap: number;
266	};
267	
268	// Enchantment carries two unrelated thresholds: 5 surcharges the premium, 8
269	// halves the reimbursement. Each predicate names the threshold it tests so the
270	// two are never mistaken for one another.
271	const isEnchantedBeyondReimbursementThreshold = (item: Item): boolean =>
272	  enchantmentOf(item) >= PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
273	
274	const isDragonMaterial = (item: Item): boolean => item.material === DRAGON_MATERIAL;
275	
276	// The reimbursement clauses decide how much of the damage is covered; the
277	// deductible is then withheld from that amount afterwards. The MHPCO applies
278	// the first clause that speaks to the damaged item, so the order below is the
279	// order of precedence: a dragon-material item enchanted to 8 or above is
280	// reimbursed in part, the enchantment clause having been reached first.
281	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
282	  {
283	    appliesTo: isEnchantedBeyondReimbursementThreshold,
284	    percentReimbursed: PARTIAL_REIMBURSEMENT_PERCENT,
285	  },
286	  { appliesTo: isDragonMaterial, percentReimbursed: FULL_REIMBURSEMENT_PERCENT },
287	];
288	
289	// An item the clauses are silent about is reimbursed in full, same as one the
290	// dragon-material clause speaks for — the MHPCO withholds only the deductible.
291	const DEFAULT_REIMBURSEMENT_PERCENT = FULL_REIMBURSEMENT_PERCENT;
292	
293	const percentReimbursedFor = (item: Item): number =>
294	  REIMBURSEMENT_CLAUSES.find((clause) => clause.appliesTo(item))
295	    ?.percentReimbursed ?? DEFAULT_REIMBURSEMENT_PERCENT;
296	
297	const reimbursementOf = (damage: Damage, item: Item): number =>
298	  percentOf(damage.amount, percentReimbursedFor(item));
299	
300	// The MHPCO does not entertain damages that would pay it.
301	const IS_NOT_NEGATIVE: Requirement<Damage> = {
302	  isMetBy: (damage) => damage.amount >= 0,
303	  reasonRejecting: (damage) =>
304	    `damage amount cannot be negative: ${damage.amount}`,
305	};
